import{_ as t,c as o,o as a,ag as r}from"./chunks/framework.B-XtCDNB.js";const p=JSON.parse('{"title":"Inventory","description":"","frontmatter":{"subtitle":"Track and manage product stock levels."},"headers":[],"relativePath":"merchant/product/inventory.md","filePath":"merchant/product/inventory.md"}'),n={name:"merchant/product/inventory.md"};function s(i,e,c,l,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to &quot;Inventory&quot;">​</a></h1><p>Meloncart includes an inventory system that tracks stock levels, prevents overselling through stock reservations, and sends low-stock notifications. Inventory tracking is optional and can be configured per product.</p><h2 id="enabling-inventory-tracking" tabindex="-1">Enabling Inventory Tracking <a class="header-anchor" href="#enabling-inventory-tracking" aria-label="Permalink to &quot;Enabling Inventory Tracking&quot;">​</a></h2><p>Inventory tracking is available when the product type has the <strong>Has Inventory</strong> feature enabled. On the product form, check the <strong>Track Inventory</strong> checkbox to activate stock management for that product.</p><p>Once enabled, the Inventory tab shows the <strong>Units in Stock</strong> field and the following settings:</p><ul><li><strong>Hidden When Out Of Stock</strong>: Automatically hides the product from the storefront when it goes out of stock.</li><li><strong>Allow Negative Stock</strong>: Allows the stock count to go below zero, useful for accepting orders beyond current inventory.</li><li><strong>Out Of Stock Threshold</strong>: An optional stock level that triggers a low-stock notification. When salable stock falls to or below this number, store managers are notified by email.</li><li><strong>Allow Pre-Order</strong>: Allows customers to purchase the product even when it is out of stock.</li></ul><h2 id="managing-stock" tabindex="-1">Managing Stock <a class="header-anchor" href="#managing-stock" aria-label="Permalink to &quot;Managing Stock&quot;">​</a></h2><p>Set the <strong>Units in Stock</strong> value on the product form in the <strong>Inventory</strong> tab. This represents the physical units on hand.</p><p>The <strong>salable quantity</strong> shown to customers is calculated as:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Salable = Units in Stock − Units Reserved</span></span></code></pre></div><p><strong>Units Reserved</strong> is managed automatically by the system: when customers place orders, stock is reserved to prevent overselling.</p><h2 id="per-variant-stock-tracking" tabindex="-1">Per-Variant Stock Tracking <a class="header-anchor" href="#per-variant-stock-tracking" aria-label="Permalink to &quot;Per-Variant Stock Tracking&quot;">​</a></h2><p>When a product uses <a href="./variants.html">variants</a>, each variant tracks its own stock independently. Set the <strong>Units in Stock</strong> for each variant in the variant&#39;s <strong>Inventory</strong> tab.</p><p>When a variant-specific combination is purchased, only that variant&#39;s stock is affected: other variants and the product-level stock remain unchanged.</p><h2 id="stock-and-order-lifecycle" tabindex="-1">Stock and Order Lifecycle <a class="header-anchor" href="#stock-and-order-lifecycle" aria-label="Permalink to &quot;Stock and Order Lifecycle&quot;">​</a></h2><p>Stock changes follow a two-phase reservation lifecycle tied to order statuses:</p><h3 id="_1-order-placed-new" tabindex="-1">1. Order Placed (New) <a class="header-anchor" href="#_1-order-placed-new" aria-label="Permalink to &quot;1. Order Placed (New)&quot;">​</a></h3><p>When a customer places an order, stock is <strong>reserved</strong> for all items in the order. The physical quantity stays the same, but the reserved count increases: reducing the salable quantity visible to other customers. This prevents overselling when multiple customers are shopping simultaneously.</p><h3 id="_2-order-shipped" tabindex="-1">2. Order Shipped <a class="header-anchor" href="#_2-order-shipped" aria-label="Permalink to &quot;2. Order Shipped&quot;">​</a></h3><p>When the order status changes to <strong>Shipped</strong>, the physical stock is <strong>decreased</strong> and the reservation is <strong>released</strong>. At this point, the units have left the warehouse.</p><h3 id="_3-order-cancelled" tabindex="-1">3. Order Cancelled <a class="header-anchor" href="#_3-order-cancelled" aria-label="Permalink to &quot;3. Order Cancelled&quot;">​</a></h3><p>If an order is cancelled before shipment, the reservation is <strong>released</strong> without changing the physical stock. The salable quantity is restored, making those units available for other customers.</p><h3 id="_4-order-refunded" tabindex="-1">4. Order Refunded <a class="header-anchor" href="#_4-order-refunded" aria-label="Permalink to &quot;4. Order Refunded&quot;">​</a></h3><p>If an order is refunded after shipment, no automatic stock adjustment occurs because the units have already left the warehouse. If the items are physically returned, you can manually increase the stock on the product form.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The order status flow for inventory is: <strong>New</strong> (reserve) → <strong>Paid</strong> (no stock action) → <strong>Shipped</strong> (decrease) or <strong>Cancelled</strong> (release). The <strong>Paid</strong> status is a billing milestone and does not affect stock.</p></div><h2 id="low-stock-notifications" tabindex="-1">Low-Stock Notifications <a class="header-anchor" href="#low-stock-notifications" aria-label="Permalink to &quot;Low-Stock Notifications&quot;">​</a></h2><p>When a product goes out of stock (or falls below its stock alert threshold), Meloncart sends an email notification to all backend users in the <strong>store-managers</strong> admin group.</p><p>To receive low-stock notifications:</p><ol><li>Create a backend user group with the code <code>store-managers</code> under <strong>Settings → Administrators → Groups</strong> (if it does not already exist).</li><li>Add the backend users who should receive notifications to this group.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The low-stock email template can be customized under <strong>Settings → Mail Templates</strong> by editing the <code>shop:low_stock_internal</code> template.</p></div><h2 id="out-of-stock-behavior" tabindex="-1">Out-of-Stock Behavior <a class="header-anchor" href="#out-of-stock-behavior" aria-label="Permalink to &quot;Out-of-Stock Behavior&quot;">​</a></h2><p>A product is considered out of stock when its salable quantity reaches zero (or falls to or below the <strong>Out Of Stock Threshold</strong>, if one is set).</p><p>Out-of-stock behavior depends on the product&#39;s settings:</p><ul><li><strong>Hidden When Out Of Stock</strong>: The product is automatically hidden from the storefront when it goes out of stock.</li><li><strong>Allow Pre-Order</strong>: Customers can still purchase the product even when it is out of stock. This is useful for upcoming products or items with a known restock date.</li><li><strong>Allow Negative Stock</strong>: The stock count can go below zero, allowing orders to be accepted beyond current inventory.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If none of these options are enabled and a product goes out of stock, it remains visible on the storefront but cannot be added to the cart.</p></div><h2 id="products-without-inventory-tracking" tabindex="-1">Products Without Inventory Tracking <a class="header-anchor" href="#products-without-inventory-tracking" aria-label="Permalink to &quot;Products Without Inventory Tracking&quot;">​</a></h2><p>When the <strong>Track Inventory</strong> checkbox is not enabled, the product is treated as always in stock. No stock fields are shown, no stock decreases occur on purchase, and no low-stock notifications are sent. This is appropriate for digital products, services, or items with unlimited availability.</p><h2 id="multi-warehouse-inventory" tabindex="-1">Multi-Warehouse Inventory <a class="header-anchor" href="#multi-warehouse-inventory" aria-label="Permalink to &quot;Multi-Warehouse Inventory&quot;">​</a></h2><p>For stores that need to track stock across multiple physical locations (warehouses), the <strong>Meloncart Inventory</strong> plugin extends the shop with warehouse-based inventory management. When installed, it replaces the simple stock field with per-warehouse stock tracking, priority-based fulfillment, and site-specific stock visibility.</p>',39)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
